mapper.select:
WITH RECURSIVE USER_MENU_TREE AS ( SELECT MENU_CODE, MENU_NM, PARENT_CODE, MENU_TYPE, USE_YN, (SELECT COMMON_CODE_NM FROM TB_COMMON_CODE_DETAIL tcd WHERE tcd.COMMON_CODE = MENU_TYPE AND tcd.UPPER_CODE = 'MENU_TYPE') AS MENU_TYPE_NM, DEPTH, PATH, SORT_ORDER, TO_CHAR(SORT_ORDER, 'FM0000000000') AS UPPER_PATH FROM TB_USER_MENU WHERE MENU_TYPE = #{menuType}
AND DEPTH = 1
UNION ALL SELECT c.MENU_CODE, c.MENU_NM, c.PARENT_CODE, c.MENU_TYPE, c.USE_YN, (SELECT COMMON_CODE_NM FROM TB_COMMON_CODE_DETAIL tcd WHERE tcd.COMMON_CODE = c.MENU_TYPE AND tcd.UPPER_CODE = 'MENU_TYPE') AS MENU_TYPE_NM, c.DEPTH, c.PATH, c.SORT_ORDER, ct.UPPER_PATH || '-' || TO_CHAR(c.SORT_ORDER, 'FM0000000000') AS UPPER_PATH FROM TB_USER_MENU c JOIN USER_MENU_TREE ct ON c.PARENT_CODE = ct.MENU_CODE WHERE 1 = 1 ) SELECT * FROM USER_MENU_TREE ORDER BY UPPER_PATH;

