UPDATE TB_USER_MENU
SET
	SORT_ORDER = #{sortOrder}
WHERE MENU_CODE = #{menuCode}

UPDATE TB_USER_MENU
SET
	SORT_ORDER = sort_order - 1
WHERE MENU_TYPE = #{menuType}
AND DEPTH = #{depth}
AND PARENT_CODE = #{parentCode}
AND SORT_ORDER > #{sortOrder}

